'use strict';
(()=>{
 const origin=document.querySelector('meta[name=justin-api-origin]')?.content||location.origin,banner=document.createElement('aside');banner.id='live-notices';banner.setAttribute('aria-label','Game announcements');document.querySelector('.ranked-note')?.after(banner)||document.querySelector('.instruction').after(banner);
 let muteUntil=0,dismissed=new Set(),generation=0,account='',lastKey='',notices=[];
 const muted=()=>Date.now()<muteUntil;
 function render(){const visible=notices.filter(n=>n.endsAt>Date.now()&&!dismissed.has(n.id)),key=JSON.stringify(visible);if(key!==lastKey){lastKey=key;banner.replaceChildren(...visible.map(n=>{const card=document.createElement('div'),text=document.createElement('p'),author=document.createElement('small'),close=document.createElement('button');text.textContent=n.message;author.textContent='announcement from '+n.author;close.type='button';close.textContent='×';close.setAttribute('aria-label','Dismiss announcement');close.onclick=()=>{dismissed.add(n.id);render()};card.append(author,text,close);return card}))}const sound=document.getElementById('audio');if(sound)sound.muted=muted();document.body.classList.toggle('account-silenced',muted())}
 function apply(data){if(!data)return;const offset=(data.serverNow||Date.now())-Date.now();muteUntil=Number(data.muteUntil||0)-offset;notices=(data.announcements||[]).map(n=>({...n,endsAt:n.endsAt-offset}));render();window.dispatchEvent(new CustomEvent('justin-sound-policy',{detail:{muted:muted(),until:muteUntil}}))}
 async function poll(){const ticket=generation;try{const r=await fetch(new URL('/api/live',origin),{credentials:'include',signal:AbortSignal.timeout(8000)});if(r.ok){const data=await r.json();if(ticket===generation)apply(data)}}catch{}}
 window.JustinLive={apply,muted};window.addEventListener('justin-account-change',e=>{const next=e.detail.user?.id||'';if(next!==account){account=next;generation++;notices=[];muteUntil=0;lastKey='';render();poll()}});document.getElementById('audio')?.addEventListener('play',render);setInterval(()=>{render();if(!document.hidden&&!window.justinOnline?.active())poll()},10000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll()});poll();
})();
